/**
 * Dashboard Tab Manager
 *
 * Handles tab navigation and state persistence using localStorage
 *
 * @package ContactInbox\Dashboard\JS
 */

const DashboardTabs = {
    storageKey: 'contactin-analytics-active-tab',
    defaultTab: 'submissions',

    /**
     * Initialize tab system
     */
    init() {
        const tabButtons = Array.from(document.querySelectorAll('.tab-button'));
        const tabPanes = Array.from(document.querySelectorAll('.tab-pane'));

        if (tabButtons.length === 0 || tabPanes.length === 0) return;

        // Restore saved tab or use default
        const saved = window.localStorage.getItem(this.storageKey) || this.defaultTab;
        this.activateTab(saved, tabButtons, tabPanes);

        // Attach click handlers
        tabButtons.forEach(btn => {
            btn.addEventListener('click', (e) => {
                const tab = btn.dataset.tab;
                this.activateTab(tab, tabButtons, tabPanes);
                window.localStorage.setItem(this.storageKey, tab);
            });
        });

        // Persist default if not set
        if (!window.localStorage.getItem(this.storageKey)) {
            window.localStorage.setItem(this.storageKey, this.defaultTab);
        }
    },

    /**
     * Activate a tab
     */
    activateTab(tab, tabButtons, tabPanes) {
        tabButtons.forEach(btn => btn.classList.toggle('active', btn.dataset.tab === tab));
        tabPanes.forEach(pane => pane.classList.toggle('active', pane.dataset.tab === tab));
    }
};

// Initialize on document ready
document.addEventListener('DOMContentLoaded', () => DashboardTabs.init());
